answer:
Gale–Shapley with proposers proposing; at each step the lexicographically smallest free proposer (that still has receivers left on its list) proposes to its next choice, and each receiver keeps whichever suitor it prefers.

```python
def stable_matching(proposers, receivers):
    # Rank tables for O(1) preference comparisons on the receiver side.
    rank = {
        r: {p: i for i, p in enumerate(prefs)}
        for r, prefs in receivers.items()
    }

    next_index = {p: 0 for p in proposers}   # next receiver to propose to
    engaged = {}                             # receiver -> proposer
    match = {}                               # proposer -> receiver

    while True:
        # Free proposers that still have someone to propose to, in string order.
        free = sorted(
            p for p in proposers
            if p not in match and next_index[p] < len(proposers[p])
        )
        if not free:
            break

        p = free[0]
        r = proposers[p][next_index[p]]
        next_index[p] += 1

        if r not in engaged:
            engaged[r] = p
            match[p] = r
        else:
            current = engaged[r]
            if rank[r].get(p, float('inf')) < rank[r].get(current, float('inf')):
                del match[current]
                engaged[r] = p
                match[p] = r
            # otherwise the receiver rejects p, who stays free

    return match
```
